import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const isCurrentOrFuture = selectedYear > currentYear || (selectedYear === currentYear && selectedMonth >= currentMonth);
    const totalReceived = isCurrentOrFuture ? 0 : (5000000 * 45);

    return (
        <div style={{
            height: 'calc(100vh - 40px)', // Trừ đi padding để không bị tràn
            display: 'flex', 
            flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, 
            backgroundSize: 'cover',
            backgroundPosition: 'center', 
            overflow: 'hidden', 
            padding: '20px',
            boxSizing: 'border-box' // Đảm bảo padding không làm tăng kích thước khung
        }} className="glass-card">

            {/* Header - Giữ chiều cao cố định thấp */}
            <div style={{ padding: '0 10px 15px 10px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý hoá đơn</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select 
                        value={selectedMonth} 
                        onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}
                    >
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select 
                        value={selectedYear} 
                        onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}
                    >
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            {/* Container chứa 2 cột - Quan trọng nhất là chiều cao ở đây */}
            <div style={{ 
                flex: 1, 
                display: 'flex', 
                gap: '25px', 
                overflow: 'hidden', // Ép các thành phần con không được tràn ra ngoài
                minHeight: 0 // Trick để flex child có thể cuộn được
            }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG */}
                <div style={{ 
                    width: '210px', 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', 
                    alignContent: 'flex-start', 
                    overflowY: 'auto',
                    padding: '12px', 
                    backgroundColor: 'rgba(255,255,255,0.15)',
                    borderRadius: '20px', 
                    border: '1px solid rgba(255,255,255,0.2)',
                    height: '100%',
                    boxSizing: 'border-box'
                }}>
                    {allRooms.map(room => (
                        <div key={room} style={{ 
                            background: !isCurrentOrFuture ? 'white' : '#ffcc00', 
                            color: '#333', padding: '8px 0', borderRadius: '8px', 
                            textAlign: 'center', fontSize: '11px', fontWeight: 'bold',
                            border: '1px solid rgba(0,0,0,0.05)', cursor: 'default'
                        }}>
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: KHUNG TRẮNG CHI TIẾT */}
                <div style={{ 
                    flex: 1, 
                    backgroundColor: '#ffffff', 
                    borderRadius: '25px', 
                    padding: '25px', 
                    display: 'flex', 
                    flexDirection: 'column',
                    color: '#333', 
                    boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)',
                    overflow: 'hidden', // Đảm bảo nội dung không lấn ra khỏi bo góc
                    height: '100%',
                    boxSizing: 'border-box'
                }}>
                    {/* Phần tổng tiền */}
                    <div style={{ 
                        marginBottom: '15px', padding: '15px 20px', backgroundColor: '#f8f9fa', 
                        borderRadius: '15px', borderLeft: '5px solid #8b5e5e', flexShrink: 0
                    }}>
                        <div style={{ fontSize: '14px', fontWeight: '600', color: '#666' }}>
                            Tổng tiền đã nhận {selectedMonth}/{selectedYear}:
                        </div>
                        <div style={{ color: totalReceived > 0 ? '#28a745' : '#bbb', fontSize: '26px', fontWeight: '800' }}>
                            {totalReceived.toLocaleString()}đ
                        </div>
                    </div>

                    <h3 style={{ borderBottom: '2px solid #eee', paddingBottom: '10px', margin: '0 0 10px 0', flexShrink: 0 }}>
                        Lịch sử giao dịch
                    </h3>

                    {/* KHU VỰC BẢNG CÓ THỂ CUỘN */}
                    <div style={{ 
                        flex: 1, 
                        overflowY: 'auto', 
                        paddingRight: '5px' 
                    }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                            <thead style={{ position: 'sticky', top: 0, backgroundColor: '#fff', zIndex: 1 }}>
                                <tr style={{ textAlign: 'left', color: '#888', fontSize: '13px' }}>
                                    <th style={{ padding: '10px', borderBottom: '2px solid #f1f1f1' }}>Phòng</th>
                                    <th style={{ padding: '10px', borderBottom: '2px solid #f1f1f1' }}>Số tiền</th>
                                    <th style={{ padding: '10px', borderBottom: '2px solid #f1f1f1' }}>Nội dung</th>
                                    <th style={{ padding: '10px', borderBottom: '2px solid #f1f1f1' }}>Thời gian</th>
                                </tr>
                            </thead>
                            <tbody>
                                {!isCurrentOrFuture ? (
                                    allRooms.map(room => (
                                        <tr key={room} style={{ borderBottom: '1px solid #f9f9f9' }}>
                                            <td style={{ padding: '12px 10px', fontWeight: 'bold' }}>{room}</td>
                                            <td style={{ padding: '12px 10px', color: '#28a745' }}>5,000,000đ</td>
                                            <td style={{ padding: '12px 10px', fontSize: '13px' }}>
                                                Tiền phòng T{selectedMonth}/{selectedYear}
                                            </td>
                                            <td style={{ padding: '12px 10px', fontSize: '11px', color: '#999' }}>
                                                01/{selectedMonth.toString().padStart(2, '0')} 09:00
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="4" style={{ textAlign: 'center', padding: '50px', color: '#ccc', fontStyle: 'italic' }}>
                                            Chưa có dữ liệu...
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default QuanLyHoaDon;
